(function(){var D='data:image/jpeg;base64,';function send(){try{window.postMessage({n7rPicture:D},'*');}catch(e){}}
window.addEventListener('message',function(e){if(e.source===window&&e.data&&e.data.n7rNeedPicture)send();});
document.addEventListener('DOMContentLoaded',function(){setTimeout(send,300);});})();
